import sys

def main():
    input = sys.stdin.read().strip().split()
    n, m = int(input[0]), int(input[1])
    max_length = n * n + 5

    # Initialize dp array
    dp = [[0] * max_length for _ in range(n)]
    dp[0][0] = 1

    # Fill dp array
    for i in range(1, n):
        for j in range(len(dp[0])):
            for c in range(i + 1):
                if j - c >= 0:
                    dp[i][j] += dp[i - 1][j - c]
                    dp[i][j] %= m
                    if dp[i][j] == 0:
                        dp[i][j] += m

    # Compute prefix sums
    sums = [[0] * len(dp[0]) for _ in range(n)]
    for i in range(n):
        s = 0
        for j in range(len(dp[0])):
            s += dp[i][j]
            s %= m
            if s == 0:
                s += m
            sums[i][j] = s

    # Precompute factorials
    fact = [1] * (501 * 501)
    for i in range(1, len(fact)):
        fact[i] = (fact[i - 1] * i) % m

    # Precompute nCr
    ncr = [[0] * 501 for _ in range(501)]
    ncr[0][0] = 1
    for i in range(1, 501):
        ncr[i][0] = 1
        for j in range(1, 501):
            ncr[i][j] = (ncr[i - 1][j] + ncr[i - 1][j - 1]) % m
            if ncr[i][j] == 0:
                ncr[i][j] += m

    result = 0
    for i in range(n - 2, -1, -1):
        cnt = n - i
        pre = n - cnt
        comb = (ncr[n][pre] * fact[pre]) % m
        if comb == 0:
            comb += m
        sum_ = 0
        for dif in range(1, cnt):
            for inv in range(dif, len(dp[0])):
                if dp[cnt - 2][inv] == 0:
                    break
                if inv - dif - 1 < 0:
                    continue
                x = dp[cnt - 2][inv]
                y = sums[cnt - 2][inv - dif - 1]
                x = (x * y) % m
                if x == 0:
                    x += m
                sum_ += (x * (cnt - dif)) % m
                sum_ %= m
        result += sum_ * comb
        result %= m
        if result == 0:
            result += m

    print(result % m)

if __name__ == "__main__":
    main()

